abstract class ReaderTemplate {
    final String run(String input) { return parse(input).trim(); }
    protected abstract String parse(String input);
}
class CsvReaderTemplate extends ReaderTemplate {
    protected String parse(String input) { return input.replace(",", "|"); }
}
public class AbstractClassOnlyDemo {
    public static void main(String[] args) { ReaderTemplate r = new CsvReaderTemplate(); System.out.println(r.run("A,B")); }
}
